const normalizarTexto = (texto: string) =>
  texto.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase();

export default function Seccion7_6Convenios({ anio, busqueda }: Seccion7_6ConveniosProps) {
  const termino = normalizarTexto(busqueda.trim());
  const conveniosAnio = conveniosPorAnio[anio] || [];
  const convenios = termino
    ? conveniosAnio.filter((convenio) =>
        Object.values(convenio).some((valor) => normalizarTexto(String(valor ?? '')).includes(termino))
      )
    : conveniosAnio;

  if (convenios.length === 0) {
    return <EstadoSinRegistros titulo="Convenios Otros Servicios Públicos" anio={anio} busqueda={busqueda} />;
  }

  return (
    <div className="space-y-4">
      {convenios.map((convenio, indice) => (
        <article key={`${anio}-${convenio.numero}-${indice}`} className="overflow-hidden rounded-xl border border-slate-200 bg-white">
          <div className="p-4">
            <div className="mb-3 inline-flex rounded-lg border border-blue-100 bg-blue-50 px-3 py-1.5 text-xs font-semibold text-blue-700">
              {convenio.tipoNorma} - {convenio.denominacion}
            </div>
            <h4 className="text-sm font-semibold text-slate-900">{convenio.nombreTitulo}</h4>
          </div>
          <div className="grid grid-cols-1 gap-4 border-t border-slate-100 bg-slate-50 p-4 sm:grid-cols-2 xl:grid-cols-4">
            <div><p className="text-xs text-slate-500">Número</p><p className="mt-1 text-xs font-medium text-slate-900">{convenio.numero}</p></div>
            <div><p className="text-xs text-slate-500">Fecha</p><p className="mt-1 text-xs font-medium text-slate-900">{convenio.fecha}</p></div>
            <div><p className="text-xs text-slate-500">Fecha, medio y forma de publicación</p><p className="mt-1 text-xs font-medium text-slate-900">{convenio.fechaPublicacion}</p></div>
            <div><p className="text-xs text-slate-500">Tiene efectos generales</p><p className="mt-1 text-xs font-medium text-slate-900">{convenio.tieneEfectosGenerales}</p></div>
            <div><p className="text-xs text-slate-500">Fecha última actualización</p><p className="mt-1 text-xs font-medium text-slate-900">{convenio.ultimaActualizacion}</p></div>
            <div><p className="text-xs text-slate-500">Breve descripción del objeto del acto</p><p className="mt-1 text-xs font-medium text-slate-900">{convenio.descripcion}</p></div>
            <div>
              <p className="text-xs text-slate-500">Enlace a la publicación o archivo</p>
              <PdfLinkButton href={convenio.urlPublicacion} ariaLabel={`Abrir PDF del convenio número ${convenio.numero}`} className="mt-1" />
            </div>
            <div>
              <p className="text-xs text-slate-500">Enlace relacionado a la modificación</p>
              {convenio.urlModificacion ? (
                <PdfLinkButton href={convenio.urlModificacion} ariaLabel={`Abrir PDF de modificación del convenio número ${convenio.numero}`} className="mt-1" />
              ) : convenio.enlaceModificacion.toLocaleLowerCase() === 'pdf' ? (
                <PdfLinkButton ariaLabel={`Abrir PDF de modificación del convenio número ${convenio.numero}`} className="mt-1" />
              ) : (
                <p className="mt-1 text-xs font-medium text-slate-900">{convenio.enlaceModificacion}</p>
              )}
            </div>
          </div>
        </article>
      ))}
    </div>
  );
}
